int a = 10, b = 3;

// Integer division — decimal is dropped
System.out.println(a / b);           // 3   (not 3.33!)

// Force double division — keep the decimal
System.out.println(a / 3.0);         // 3.3333...
System.out.println((double) a / b);  // 3.3333...  (cast)

// double operand — result is always double
double price = 7.50;
int    items = 2;
System.out.println(price / items);   // 3.75

int x = 10;

x += 5;   System.out.println(x);  // 15  (10 + 5)
x -= 3;   System.out.println(x);  // 12  (15 - 3)
x *= 2;   System.out.println(x);  // 24  (12 * 2)
x /= 4;   System.out.println(x);  // 6   (24 / 4)
x %= 4;   System.out.println(x);  // 2   (6 % 4)

// Expanded form of x += 5:
// x = x + 5;  — identical result, more typing

int x = 5;

x++;  System.out.println(x);  // 6
x++;  System.out.println(x);  // 7
x--;  System.out.println(x);  // 6
x--;  System.out.println(x);  // 5  (back to start)

// All three are identical:
x = x + 1;  // explicit assignment
x += 1;     // augmented assignment
x++;        // increment — most concise

