import java.util.Scanner;

public class ShoppingCart {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char currency = '$';

        System.out.print("What would you like to buy? ");
        String item = scanner.nextLine();

        System.out.print("Price per item (" + currency + "): ");
        double price = scanner.nextDouble();

        System.out.print("How many? ");
        int quantity = scanner.nextInt();
        scanner.close();

        double total = price * quantity;
        System.out.println("\nYou bought " + quantity + " x " + item);
        System.out.println("Total: " + currency + total);
    }
}

// Two-item cart with optional discount
double price1 = 24.99, price2 = 14.99;
int    qty1   = 2,     qty2   = 3;

double grandTotal = (price1 * qty1) + (price2 * qty2);

System.out.println("Subtotal: $" + grandTotal);

if (grandTotal > 50) {
    grandTotal *= 0.90;  // apply 10% discount
    System.out.println("10% discount applied!");
}

System.out.println("Total: $" + grandTotal);

int age = 20;

if (age >= 18) {
    System.out.println("You are an adult."); // runs — 20 >= 18
}

int score = 45;
if (score >= 60) {
    System.out.println("Passing."); // skipped — 45 < 60
}

System.out.println("Program continues here regardless.");

int age = 14;

if (age >= 18) {
    System.out.println("Adult");
} else if (age >= 13) {
    System.out.println("Teenager");    // <- this branch runs
} else if (age >= 0) {
    System.out.println("Child");
} else {
    System.out.println("Invalid age"); // fallback
}

// Only one message is ever printed.

int score = 75;

if (score == 100) System.out.println("Perfect!");
if (score != 100) System.out.println("Not perfect.");  // runs
if (score >= 60)  System.out.println("Passing.");       // runs
if (score < 50)   System.out.println("Failing.");       // skipped

// String equality — always use .equals()
String name = "Alice";
if (name.equals("Alice")) {
    System.out.println("Hello, Alice!");
}
// WRONG: if (name == "Alice") -- unreliable for Strings

boolean isStudent   = true;
boolean hasDiscount = false;

// Clean boolean checks — no == true needed
if (isStudent) {
    System.out.println("Student rate applied.");
}

if (!hasDiscount) {
    System.out.println("No discount on file.");
}

// Logical AND — both must be true
if (isStudent && !hasDiscount) {
    System.out.println("You qualify for a student discount!");
}
